"""Step 2 input contract: Blosm reference polylines and indexed topology.

Python supplies no fillets, mouth stations, sector controls, or surface samples.
Each Section keeps its original directed centerline and EDGE width/offset.
Metadata is namespaced ``s2_`` and lives on isolated POINT records. Absolute
vertex/edge references address the complete carrier; view indices address rows
selected by ``s2_record_type``. Separate Section endpoints are intentionally not
welded, even when coincident: chain order and connectivity are explicit data.
"""
from dataclasses import dataclass
import math

SCHEMA_VERSION = 1
HEADER, PATH_VERTEX, SECTION, STREET, CONNECTOR, MEMBER, PROFILE = range(7)
STREET_ITEM, BUNDLE_ITEM = 0, 1
FLAT, SMOOTH_CROWN = 0, 1

INTS = (
    's2_record_type', 's2_record_index', 's2_schema_version', 's2_source_id',
    's2_connector_count', 's2_street_count', 's2_section_count',
    's2_member_count', 's2_profile_count', 's2_path_vertex_count',
    's2_street_index', 's2_section_index', 's2_chain_index',
    's2_vertex_start', 's2_vertex_count', 's2_vertex_order',
    's2_edge_start', 's2_edge_count', 's2_section_start',
    's2_connector_index', 's2_member_start', 's2_profile_index',
    's2_item_kind', 's2_bundle_index', 's2_bundle_source_id',
    's2_section_ref', 's2_endpoint_vertex', 's2_next_vertex',
    's2_far_vertex', 's2_endpoint_edge', 's2_lateral_order',
    's2_head_order', 's2_tail_order', 's2_preset', 's2_half_profile',
)
FLOATS = ('s2_cell_size', 's2_datum', 's2_width', 's2_offset',
          's2_radius', 's2_rise')
BOOLS = ('s2_leaving', 's2_separator')
VECTORS = ('s2_junction_position',)
SCHEMA = {**{n: 'INT' for n in INTS}, **{n: 'FLOAT' for n in FLOATS},
          **{n: 'BOOLEAN' for n in BOOLS},
          **{n: 'FLOAT_VECTOR' for n in VECTORS}}
EDGE_SCHEMA = {'width': 'FLOAT', 'offset': 'FLOAT', 'section_index': 'INT',
               's2_edge_street_index': 'INT', 's2_edge_section_ref': 'INT',
               's2_edge_order': 'INT'}


def _point(value):
    v = tuple(float(x) for x in value)
    if len(v) == 2:
        v = (*v, 0.)
    if len(v) != 3 or not all(math.isfinite(x) for x in v):
        raise ValueError('Centerline coordinates must have 2 or 3 finite values')
    return v


