@dataclass(frozen=True)
class PreparedJunction:
    source_id: int
    location: tuple
    streets: tuple
    connectors: tuple
    profiles: tuple
    datum: float = 0.
    cell_size: float = .7


def _finite(value, label, *, positive=False):
    if not math.isfinite(value) or (positive and value <= 0):
        raise ValueError(label+' must be '+('positive and ' if positive else '')+'finite')


def validate(junction):
    """Validate serialization, independently of the narrower first GN kernel."""
    _point(junction.location)
    _finite(junction.datum, 'Junction datum')
    _finite(junction.cell_size, 'Target cell size', positive=True)
    if len(junction.connectors) < 3:
        raise ValueError('An intersection requires at least three connectors')
    if not junction.profiles or not junction.streets:
        raise ValueError('Street and profile records are required')
    for street in junction.streets:
        if not street.sections:
            raise ValueError('An exported Street requires at least one Section')
        previous = None
        for index, section in enumerate(street.sections):
            if section.chain_index != index:
                raise ValueError('Section chain_index must match its Street order')
            _finite(section.width, 'Section width', positive=True)
            _finite(section.offset, 'Section offset')
            points = [_point(p) for p in section.centerline]
            if len(points) < 2:
                raise ValueError('Section centerlines require at least two points')
            if any(math.dist(a, b) < 1.e-8 for a, b in zip(points, points[1:])):
                raise ValueError('Zero-length centerline segments are unsupported')
            if previous is not None and math.dist(previous, points[0]) > 1.e-5:
                raise ValueError('Section chain endpoints do not meet')
            previous = points[-1]
    for profile in junction.profiles:
        _finite(profile.rise, 'Profile rise')
        if profile.rise < 0:
            raise ValueError('Profile rise must not be negative')
        if profile.preset not in (FLAT, SMOOTH_CROWN):
            raise ValueError('Initial profile presets are flat and smooth crown')
        if profile.preset == FLAT and profile.rise != 0.:
            raise ValueError('A flat profile must have zero rise')
        if profile.half_profile not in (-1, 0, 1):
            raise ValueError('Half-profile side must be -1, 0 or +1')
        if profile.half_profile and profile.separator:
            raise ValueError('A single-member half-profile is distinct from a paired separator profile')
    used = []
    endpoint_refs = set()
    for connector in junction.connectors:
        if connector.item_kind not in (STREET_ITEM, BUNDLE_ITEM):
            raise ValueError('Connector item kind must be Street or Bundle')
        if not 0 <= connector.profile_index < len(junction.profiles):
            raise ValueError('Invalid connector profile reference')
        if not connector.members:
            raise ValueError('Connector has no constituent Streets')
        if connector.item_kind == STREET_ITEM and len(connector.members) != 1:
            raise ValueError('A Street connector has exactly one member')
        _finite(connector.radius, 'Corner radius', positive=True)
        for member in connector.members:
            if not 0 <= member.street_index < len(junction.streets):
                raise ValueError('Invalid member Street reference')
            street = junction.streets[member.street_index]
            section = street.sections[0 if member.leaving else -1]
            endpoint = (street.source_id, section.source_id, int(not member.leaving))
            if endpoint in endpoint_refs:
                raise ValueError('An original Street/Section endpoint may enter a junction only once')
            endpoint_refs.add(endpoint)
            used.append(member.street_index)
    if len(set(used)) != len(used):
        raise ValueError('A Street may enter this single-junction carrier only once')
    if set(used) != set(range(len(junction.streets))):
        raise ValueError('Every exported Street must be referenced by a connector')


def _outward(section, leaving):
    points = [_point(p) for p in section.centerline]
    return points if leaving else points[::-1]


def validate_initial_scope(junction):
    """Reject unsupported inputs; do not straighten paths or collapse Bundles.

    Version 1 solves one flat, ordinary major junction. Its local input domain
    has one straight Section per member, no lane-transition items, one or two
    co-directed straight members per connector, explicit shared profiles, and CCW arms.
    The carrier itself retains full paths; later kernels can widen this domain.
    """
    validate(junction)
    active_profiles = tuple(junction.profiles[c.profile_index] for c in junction.connectors)
    if any(p.half_profile for p in active_profiles):
        if max(p.rise for p in active_profiles)-min(p.rise for p in active_profiles)>1e-7:
            raise ValueError('Half-profile junctions currently require a common incoming rise')
        # A zero-width half-sector is one complete median-side boundary. A
        # single collapsed end would leave a degenerate wedge at its mouth.
        sides = [junction.profiles[c.profile_index].half_profile for c in junction.connectors]
        for first, second in zip(sides, sides[1:]+sides[:1]):
            if (first == -1) != (second == 1):
                raise ValueError('Half-profile inner edges must form a complete adjacent plateau boundary')
    location = _point(junction.location)
    angles = []
    for connector in junction.connectors:
        if len(connector.members) > 2:
            raise ValueError('Initial solver supports at most two members per connector')
        profile = junction.profiles[connector.profile_index]
        if len(connector.members) == 2 and not profile.separator:
            raise ValueError('Two members require an explicit separator/profile specification')
        if len(connector.members) == 1 and profile.separator:
            raise ValueError('A separator requires two separate carriageway paths')
        directions = []
        displacements = []
        lateral = []
        widths = []
        for member in connector.members:
            street = junction.streets[member.street_index]
            if len(street.sections) != 1:
                raise ValueError('Initial solver requires one Section per local approach; section transitions are preserved but not solved')
            section = street.sections[0]
            tags = dict(section.tags)
            if (str(tags.get('bridge', 'no')).lower() not in ('no', 'false', '0', '') or
                str(tags.get('tunnel', 'no')).lower() not in ('no', 'false', '0', '') or
                str(tags.get('layer', '0')) not in ('0', '0.0', '')):
                raise ValueError('Initial solver requires an explicitly ground-level junction')
            if section.category in ('tram', 'rail', 'light_rail', 'subway', 'runway', 'taxiway'):
                raise ValueError('Rail/aeroway components require a future explicit surface model')
            points = _outward(section, member.leaving)
            if any(abs(p[2]-location[2]) > 1.e-6 for p in points):
                raise ValueError('Terrain and nonplanar approach centerlines need an alignment stage')
            delta = tuple(b-a for a, b in zip(points[0], points[-1]))
            length = math.hypot(delta[0], delta[1])
            if length < 1.e-6:
                raise ValueError('Approach has no outward extent')
            direction = (delta[0]/length, delta[1]/length)
            stations = []
            for p in points:
                dx, dy = p[0]-points[0][0], p[1]-points[0][1]
                if abs(dx*direction[1]-dy*direction[0]) > 1.e-5:
                    raise ValueError('Curved local approaches are retained but not supported by the initial kernel')
                stations.append(dx*direction[0]+dy*direction[1])
            if any(b <= a for a, b in zip(stations, stations[1:])):
                raise ValueError('Approach centerline doubles back')
            directions.append(direction)
            displacements.append(delta)
            outward_offset = section.offset if member.leaving else -section.offset
            # Positive offset is to the right of the original directed path.
            right = (direction[1], -direction[0])
            lateral.append((points[0][0]-location[0])*right[0] +
                           (points[0][1]-location[1])*right[1] + outward_offset)
            widths.append(section.width)
        tilted = any(math.dist(directions[0], d) > 1.e-5 for d in directions[1:])
        direction = directions[0]
        if tilted:
            delta = tuple(sum(d[k] for d in displacements) for k in (0, 1))
            length = math.hypot(*delta)
            if length < 1e-6:
                raise ValueError('Bundle members need a common outward axis')
            direction = tuple(v/length for v in delta)
            if any(sum(a*b for a,b in zip(direction,d)) <= .5 for d in directions):
                raise ValueError('Bundle members must advance along their common outward axis')
        if not tilted and len(lateral) == 2 and abs(lateral[1]-lateral[0]) <= .5*sum(widths)+1.e-6:
            raise ValueError('Selected Bundle members overlap or leave no separator gap')
        angles.append(math.atan2(direction[1], direction[0]))
    gaps = [(angles[(i+1) % len(angles)]-a) % math.tau for i, a in enumerate(angles)]
    if min(gaps) < 1.e-4 or abs(sum(gaps)-math.tau) > 1.e-4:
        raise ValueError('Connector order must make exactly one counterclockwise turn')
    # Equal/straight-through neighbors are legal (e.g. the back of a T).
    if max(gaps) > math.pi*7./6.+1.e-4:
        raise ValueError('Corner construction supports outer arm gaps up to 210 degrees')


def serialize(junction):
    """Return vertices, edges, POINT rows, EDGE rows, all deterministic."""
    validate(junction)
    vertices, edges, rows, edge_rows = [], [], [], []
    section_rows, street_rows, connector_rows, member_rows = [], [], [], []
    lookup = {}
    for street_index, street in enumerate(junction.streets):
        section_start = len(section_rows)
        for section in street.sections:
            section_ref = len(section_rows)
            vertex_start, edge_start = len(vertices), len(edges)
            points = [_point(p) for p in section.centerline]
            for order, point in enumerate(points):
                vertices.append(point)
                rows.append(dict(s2_record_type=PATH_VERTEX,
                                 s2_record_index=vertex_start+order,
                                 s2_street_index=street_index,
                                 s2_section_index=section_ref,
                                 s2_vertex_order=order))
            for order in range(len(points)-1):
                edges.append((vertex_start+order, vertex_start+order+1))
                edge_rows.append(dict(width=float(section.width), offset=float(section.offset),
                                      section_index=section.chain_index,
                                      s2_edge_street_index=street_index,
                                      s2_edge_section_ref=section_ref,
                                      s2_edge_order=order))
            record = dict(s2_record_type=SECTION, s2_record_index=section_ref,
                          s2_source_id=section.source_id, s2_section_index=section_ref,
                          s2_street_index=street_index, s2_chain_index=section.chain_index,
                          s2_vertex_start=vertex_start, s2_vertex_count=len(points),
                          s2_edge_start=edge_start, s2_edge_count=len(points)-1,
                          s2_width=float(section.width), s2_offset=float(section.offset))
            section_rows.append(record)
            lookup[street_index, section.chain_index] = record
        street_rows.append(dict(s2_record_type=STREET, s2_record_index=street_index,
                                s2_street_index=street_index, s2_source_id=street.source_id,
                                s2_section_start=section_start,
                                s2_section_count=len(street.sections)))
    for index, connector in enumerate(junction.connectors):
        member_start = len(member_rows)
        for member in connector.members:
            section_index = 0 if member.leaving else len(junction.streets[member.street_index].sections)-1
            section = lookup[member.street_index, section_index]
            first = section['s2_vertex_start']
            last = first+section['s2_vertex_count']-1
            endpoint = first if member.leaving else last
            member_rows.append(dict(
                s2_record_type=MEMBER, s2_record_index=len(member_rows),
                s2_connector_index=index, s2_street_index=member.street_index,
                s2_section_ref=section['s2_section_index'],
                s2_endpoint_vertex=endpoint,
                s2_next_vertex=endpoint+(1 if member.leaving else -1),
                s2_far_vertex=last if member.leaving else first,
                s2_endpoint_edge=section['s2_edge_start']+(0 if member.leaving else section['s2_edge_count']-1),
                s2_leaving=member.leaving, s2_lateral_order=member.lateral_order,
                s2_bundle_index=member.bundle_index,
                s2_head_order=member.head_order, s2_tail_order=member.tail_order))
        connector_rows.append(dict(
            s2_record_type=CONNECTOR, s2_record_index=index,
            s2_connector_index=index, s2_source_id=connector.source_id,
            s2_member_start=member_start, s2_member_count=len(connector.members),
            s2_profile_index=connector.profile_index,
            s2_radius=float(connector.radius), s2_item_kind=connector.item_kind,
            s2_leaving=connector.leaving, s2_bundle_source_id=connector.bundle_source_id))
    profile_rows = [dict(s2_record_type=PROFILE, s2_record_index=i,
                         s2_profile_index=i, s2_rise=float(p.rise),
                         s2_preset=p.preset, s2_separator=p.separator, s2_half_profile=p.half_profile)
                    for i, p in enumerate(junction.profiles)]
    header = dict(s2_record_type=HEADER, s2_record_index=0,
                  s2_schema_version=SCHEMA_VERSION, s2_source_id=junction.source_id,
                  s2_connector_count=len(connector_rows), s2_street_count=len(street_rows),
                  s2_section_count=len(section_rows), s2_member_count=len(member_rows),
                  s2_profile_count=len(profile_rows), s2_path_vertex_count=len(vertices),
                  s2_cell_size=float(junction.cell_size), s2_datum=float(junction.datum),
                  s2_junction_position=_point(junction.location))
    for row in [header, *section_rows, *street_rows, *connector_rows, *member_rows, *profile_rows]:
        rows.append(row)
        vertices.append((0., 0., 0.))
    return vertices, edges, rows, edge_rows


def carrier_mesh(junction, name=None):
    """Create the modifier's one Geometry input; never produces surface faces."""
    import bpy
    vertices, edges, rows, edge_rows = serialize(junction)
    mesh = bpy.data.meshes.new(name or 'Blosm Section centerlines and junction records')
    mesh.from_pydata(vertices, edges, [])
    for domain, schema, records in (('POINT', SCHEMA, rows), ('EDGE', EDGE_SCHEMA, edge_rows)):
        for name, kind in schema.items():
            attribute = mesh.attributes.new(name=name, type=kind, domain=domain)
            if kind == 'FLOAT_VECTOR':
                values = [component for row in records for component in row.get(name, (0., 0., 0.))]
                attribute.data.foreach_set('vector', values)
            else:
                attribute.data.foreach_set('value', [row.get(name, False if kind == 'BOOLEAN' else 0) for row in records])
    mesh['step2_schema_version'] = SCHEMA_VERSION
    mesh['input_kind'] = 'Original-directed Section centerlines, explicit Blosm connectivity, design profiles'
    mesh.update()
    return mesh
